package com.kareem.cortex;

import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.view.*;
import android.widget.*;

/** Technical internals are intentionally isolated here, away from daily Cortex screens. */
public class EnvironmentActivity extends Activity {
    static final int REQ_TREE=701;
    VaultDb db;LinearLayout box;TextView auditState,modelState,runtimeState,folderState,ocrState,providerState;ProgressBar auditProgress,modelProgress;Button auditAction,modelAction,runtimeAction;Handler handler=new Handler(Looper.getMainLooper());boolean verifying=false,auditStarting=false,functionalTesting=false;
    int dp(int x){return CortexUi.dp(this,x);}TextView tv(String s,int sp,int c){return CortexUi.plain(this,s,sp,c);}
    @Override public void onCreate(Bundle b){super.onCreate(b);CortexUi.applyWindow(this);db=new VaultDb(this);V41Maintenance.run(this,db);VisualInsightStore.ensure(db);CortexAuditStore.ensure(db);build();requestNotificationPermission();refresh();handler.postDelayed(()->LocalLlmRuntime.maybeAutoSelfTest(this,s->runOnUiThread(this::refresh)),800);}
    @Override protected void onResume(){super.onResume();refresh();handler.post(ticker);ScreenshotWorkScheduler.kick(this);}
    @Override protected void onPause(){super.onPause();handler.removeCallbacks(ticker);}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(db!=null)try{db.close();}catch(Throwable ignored){}db=null;super.onDestroy();}
    Runnable ticker=new Runnable(){public void run(){if(!isFinishing()&&!isDestroyed()){refresh();handler.postDelayed(this,1000);}}};

    void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(CortexUi.BG);ScrollView sv=new ScrollView(this);box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(14),dp(20),dp(28));sv.addView(box);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.HORIZONTAL);head.setGravity(Gravity.CENTER_VERTICAL);TextView back=CortexUi.plain(this,"‹",34,CortexUi.TEXT);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->finish());head.addView(back,new LinearLayout.LayoutParams(dp(42),dp(48)));TextView h=CortexUi.plain(this,"Advanced diagnostics",27,CortexUi.TEXT);CortexUi.medium(h);head.addView(h,new LinearLayout.LayoutParams(0,-2,1));box.addView(head);
        box.addView(CortexUi.section(this,"External AI"));providerState=statusCard("Configured provider");Button externalCheck=button("Run external model check");externalCheck.setOnClickListener(v->startActivity(new Intent(this,ExternalModelCheckActivity.class)));box.addView(externalCheck,lp());
        box.addView(CortexUi.section(this,"Local model"));modelState=statusCard("Local model");modelProgress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);modelProgress.setMax(100);box.addView(modelProgress,progressLp());modelAction=button("Download model");modelAction.setOnClickListener(v->modelAction());box.addView(modelAction,lp());Button remove=button("Remove local model");remove.setOnClickListener(v->{LocalModelManager.remove(this);refresh();});box.addView(remove,lp());runtimeState=statusCard("Inference runtime");runtimeAction=button("Run self-test");runtimeAction.setOnClickListener(v->runSelfTest());box.addView(runtimeAction,lp());
        box.addView(CortexUi.section(this,"Processing"));folderState=statusCard("Screenshot source");Button choose=button("Connect screenshot folder");choose.setOnClickListener(v->chooseTree());box.addView(choose,lp());Button scan=button("Scan new screenshots");scan.setOnClickListener(v->scan());box.addView(scan,lp());Button repair=button("Repair screenshot archive");repair.setOnClickListener(v->repairScreens());box.addView(repair,lp());ocrState=statusCard("Image extraction");Button ocrLab=button("Open OCR test lab");ocrLab.setOnClickListener(v->startActivity(new Intent(this,OcrTestActivity.class)));box.addView(ocrLab,lp());
        box.addView(CortexUi.section(this,"Quality"));Button functional=button("Run intelligence functional self-test");functional.setOnClickListener(v->runFunctionalSelfTest(functional));box.addView(functional,lp());Button relevance=button("Relevance evaluation");relevance.setOnClickListener(v->startActivity(new Intent(this,RelevanceEvaluationActivity.class)));box.addView(relevance,lp());Button liveStatus=button("Live processing status");liveStatus.setOnClickListener(v->startActivity(new Intent(this,CortexStatusActivity.class)));box.addView(liveStatus,lp());
        box.addView(CortexUi.section(this,"System"));auditState=statusCard("Application audit");auditProgress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);auditProgress.setMax(1000);box.addView(auditProgress,progressLp());auditAction=button("Run full app audit");auditAction.setOnClickListener(v->auditAction());box.addView(auditAction,lp());Button export=button("Export debug package");export.setOnClickListener(v->{if(db!=null)DebugExporter.exportAndShare(this,db);});box.addView(export,lp());setContentView(root);CortexUi.fitSystemBars(this,root);}

    TextView statusCard(String title){LinearLayout c=CortexUi.card(this,18);c.setPadding(dp(14),dp(12),dp(14),dp(12));TextView h=CortexUi.plain(this,title,12,CortexUi.TEXT);CortexUi.medium(h);c.addView(h);TextView state=CortexUi.text(this,"",12,CortexUi.MUTED);state.setPadding(0,dp(6),0,0);c.addView(state);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(8));box.addView(c,p);return state;}Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(11);b.setTextColor(CortexUi.TEXT);b.setAllCaps(false);b.setBackground(CortexUi.round(this,CortexUi.SURFACE,android.graphics.Color.TRANSPARENT,15));return b;}LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(46));p.setMargins(0,0,0,dp(8));return p;}LinearLayout.LayoutParams progressLp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(7));p.setMargins(0,0,0,dp(9));return p;}

    void refresh(){if(db==null)return;CortexAuditStore.Run ar=CortexAuditStore.latest(db);if(auditStarting){auditState.setText("Preparing audit…");auditProgress.setProgress(10);auditAction.setText("Starting…");auditAction.setEnabled(false);}else if(ar==null){auditState.setText("Not run yet • "+CortexAuditStore.defs().size()+" registered checks");auditProgress.setProgress(0);auditAction.setText("Run full app audit");auditAction.setEnabled(true);}else{int p=ar.progress();auditState.setText(ar.status.toUpperCase(java.util.Locale.ROOT)+" • "+p+"%"+(ar.phase.isEmpty()?"":"\n"+ar.phase)+(ar.currentTest.isEmpty()?"":"\n"+ar.currentTest));auditState.setTextColor("complete".equals(ar.status)?CortexUi.SAGE:CortexUi.MUTED);auditProgress.setProgress(p*10);auditAction.setText(ar.active()?"Open audit • "+p+"%":"Open audit results");auditAction.setEnabled(true);}
        LocalModelManager.Status s=LocalModelManager.status(this);StringBuilder d=new StringBuilder(s.label);if(s.percent>0)d.append(" • ").append(s.percent).append('%');if(s.done>0)d.append(" • ").append(LocalModelManager.human(s.done)).append(s.total>0?" / "+LocalModelManager.human(s.total):"");if(!s.detail.isEmpty())d.append("\n").append(s.detail);if(s.partialBytes>0&&!s.verified)d.append("\nPartial: ").append(LocalModelManager.human(s.partialBytes));modelState.setText(d.toString());modelState.setTextColor(s.failed?android.graphics.Color.rgb(246,124,118):(s.verified?CortexUi.SAGE:CortexUi.MUTED));modelProgress.setProgress(Math.max(0,Math.min(100,s.percent)));modelAction.setEnabled(!verifying);if(verifying)modelAction.setText("Verifying…");else if(s.verified)modelAction.setText("Model verified");else if("downloading".equals(s.state)||"connecting".equals(s.state)||"retrying".equals(s.state))modelAction.setText("Pause download");else if("paused".equals(s.state)||"failed".equals(s.state)||"canceled".equals(s.state))modelAction.setText(s.partialBytes>0?"Resume download":"Start download");else if(LocalModelManager.filePresent(this)||"downloaded".equals(s.state))modelAction.setText("Verify downloaded model");else modelAction.setText("Download model");
        LocalLlmRuntime.State rt=LocalLlmRuntime.state(this);StringBuilder r=new StringBuilder(rt.label());if(rt.tokensPerSecond>0)r.append("\n").append(String.format(java.util.Locale.US,"%.2f tok/s",rt.tokensPerSecond)).append(" • ").append(rt.tokensGenerated).append(" tokens • ").append(rt.durationMs).append(" ms");if(!rt.selfTestText.isEmpty())r.append("\nSelf-test: ").append(clip(rt.selfTestText,120));if(!rt.error.isEmpty())r.append("\n").append(rt.error);runtimeState.setText(r.toString());runtimeState.setTextColor("ready".equals(rt.state)?CortexUi.SAGE:("failed".equals(rt.state)?android.graphics.Color.rgb(246,124,118):CortexUi.MUTED));runtimeAction.setEnabled(s.verified&&!"testing".equals(rt.state));runtimeAction.setText("testing".equals(rt.state)?"Running self-test…":("ready".equals(rt.state)?"Run self-test again":"Run self-test"));
        folderState.setText(ScreenshotIngestor.tree(this)==null?"Not connected":"Connected • "+ScreenshotIngestor.treeLabel(this));int queued=count("SELECT COUNT(*) FROM knowledge_items WHERE source='screenshot-folder' AND type IN ('SCREENSHOT','IMAGE') AND status='queued'");int analyzing=count("SELECT COUNT(*) FROM knowledge_items WHERE source='screenshot-folder' AND type IN ('SCREENSHOT','IMAGE') AND status='analyzing'");int analyzed=count("SELECT COUNT(*) FROM knowledge_items WHERE source='screenshot-folder' AND type IN ('SCREENSHOT','IMAGE') AND status='analyzed'");int visual=VisualInsightStore.countDone(db);ocrState.setText("Searchable: "+analyzed+" • queued "+queued+" • processing "+analyzing+"\nVisual understanding: "+visual);
        String primaryProvider=ExternalBrainProvider.activeProviderId(this),primaryModel=ExternalBrainProvider.activeModel(this);StringBuilder provider=new StringBuilder("Primary Brain: ").append(primaryProvider).append(" · ").append(primaryModel);if(OpenRouterKeyStore.has(this))provider.append("\nOpenRouter configured · OX Alpha is the primary remote reasoning route");else if(GeminiKeyStore.has(this))provider.append("\nOpenRouter not configured · Gemini fallback is currently active");else provider.append("\nOpenRouter not configured · add an OpenRouter key to enable OX Alpha");provider.append("\nVision/fallback: ").append(GeminiKeyStore.has(this)?("Gemini · "+GeminiModelConfig.generationModel(this)):"Gemini not configured");provider.append("\nCombined Brain falls back locally if the remote route fails.");providerState.setText(provider.toString());}

    void runFunctionalSelfTest(Button button){if(functionalTesting)return;functionalTesting=true;button.setEnabled(false);button.setText("Running functional self-test…");new Thread(()->{CortexFunctionalSelfTest.Report report=CortexFunctionalSelfTest.run(getApplicationContext());runOnUiThread(()->{functionalTesting=false;if(isFinishing()||isDestroyed())return;button.setEnabled(true);button.setText("Run intelligence functional self-test");TextView text=CortexUi.text(this,report.text(),12,CortexUi.TEXT);text.setTextIsSelectable(true);int pad=dp(18);text.setPadding(pad,pad,pad,pad);ScrollView s=new ScrollView(this);s.addView(text);new AlertDialog.Builder(this).setTitle(report.ok()?"Cortex functions passed":"Cortex function failures found").setView(s).setPositiveButton("Close",null).show();});},"CortexFunctionalSelfTest").start();}
    void auditAction(){CortexAuditStore.Run r=CortexAuditStore.latest(db);if(r!=null){startActivity(new Intent(this,CortexAuditActivity.class));return;}auditStarting=true;refresh();new Thread(()->{try{CortexAuditScheduler.start(this);runOnUiThread(()->{auditStarting=false;refresh();startActivity(new Intent(this,CortexAuditActivity.class));});}catch(Exception e){runOnUiThread(()->{auditStarting=false;auditState.setText("Audit could not start");auditAction.setEnabled(true);auditAction.setText("Try again");});}},"CortexAuditStartFromEnvironment").start();}
    int count(String sql){Cursor c=db.getReadableDatabase().rawQuery(sql,null);int n=c.moveToFirst()?c.getInt(0):0;c.close();return n;}String clip(String s,int n){return s.length()<=n?s:s.substring(0,n)+"…";}void runSelfTest(){if(!LocalModelManager.verified(this)){Toast.makeText(this,"Verify the local model first",Toast.LENGTH_LONG).show();return;}LocalLlmRuntime.runSelfTest(this,state->runOnUiThread(this::refresh));refresh();}void modelAction(){LocalModelManager.Status s=LocalModelManager.status(this);if(s.verified){runSelfTest();return;}if("downloading".equals(s.state)||"connecting".equals(s.state)||"retrying".equals(s.state)){LocalModelManager.pauseDownload(this);return;}if("paused".equals(s.state)||"failed".equals(s.state)||"canceled".equals(s.state)){LocalModelManager.resumeDownload(this);return;}if(LocalModelManager.filePresent(this)||"downloaded".equals(s.state)){verifyModel();return;}LocalModelManager.startDownload(this);refresh();}void verifyModel(){if(verifying)return;verifying=true;refresh();new Thread(()->{LocalModelManager.Verification v=LocalModelManager.verify(this);runOnUiThread(()->{verifying=false;refresh();if(v.ok)LocalLlmRuntime.maybeAutoSelfTest(this,state->runOnUiThread(this::refresh));});}).start();}
    void requestNotificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},702);}void chooseTree(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,REQ_TREE);}@Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==REQ_TREE&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}ScreenshotIngestor.saveTree(this,u);refresh();scan();}}void scan(){if(ScreenshotIngestor.tree(this)==null){Toast.makeText(this,"Connect the screenshot folder first",Toast.LENGTH_LONG).show();return;}new Thread(()->{try{ScreenshotIngestor.Result r=ScreenshotIngestor.scan(this,db,3000);ScreenshotWorkScheduler.kick(this);runOnUiThread(()->Toast.makeText(this,"Imported "+r.imported+" • duplicates "+r.duplicates,Toast.LENGTH_LONG).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Scan failed",Toast.LENGTH_LONG).show());}}).start();}void repairScreens(){if(ScreenshotIngestor.tree(this)==null){Toast.makeText(this,"Connect the screenshot folder first",Toast.LENGTH_LONG).show();return;}new Thread(()->{int n=ScreenshotIngestor.repairMissingAttachments(this,db,5000);ScreenshotWorkScheduler.kick(this);runOnUiThread(()->Toast.makeText(this,"Repaired "+n+" screenshots",Toast.LENGTH_LONG).show());}).start();}
}
